window.MN=window.MN||{},MN.Drought=function(){const t={};return{compute:async function(e){if(t[e.slug])return t[e.slug];const n=new Date;n.setDate(n.getDate()-6);const r=n.toISOString().slice(0,10),o=await MN.WX.fetchPrecipHistory(e,"1995-01-01",r);if(!o.length)return null;const a=o.slice(-30),c=a.reduce((t,e)=>t+e.p,0),s={};o.forEach(t=>{const e=+t.date.slice(0,4);if(e<1995||e>2024)return;const n=t.date.slice(5);(s[n]=s[n]||[]).push(t.p)});let u=0;a.forEach(t=>{const e=t.date.slice(5),n=s[e];n&&n.length>=20&&(u+=n.reduce((t,e)=>t+e,0)/n.length)});let l=null,i="normal";u>=5?(l=Math.round(c/u*100),l<40?i="drought":l<70?i="dry":l>140&&(i="wet")):c<5?(l=100,i="normal"):(l=Math.round(c/Math.max(u,1)*100),i="wet");const h={lastSum:Math.round(c),normal:Math.round(u),pct:l,status:i,asOf:a[a.length-1].date};return t[e.slug]=h,h}}}();